export function resolvePageKey(pathname: string): PageKey | "unknown" {
  let best: PageManifestEntry | undefined
  for (const entry of PAGE_MANIFEST) {
    if (pathname === entry.route || pathname.startsWith(entry.route.replace(/\/$/, "") + "/")) {
      if (!best || entry.route.length > best.route.length) best = entry
    }
  }
  return best ? best.key : "unknown"
}

export function getPageEntry(key: string): PageManifestEntry | undefined {
  return PAGE_MANIFEST.find((e) => e.key === key)
}
